insert into public.exercises(id,name,english_name,description,category,equipment,primary_muscle,instructions,tips,mistakes,load_kind,supports_1rm) values ('11000000-0000-4000-8000-164509db1b57','Technogym Selection 900 — Chest Press (Développé poitrine)','Selection 900 Chest Press','Réglez le siège pour placer les poignées près du milieu de la poitrine. Poussez sans décoller le dos, puis revenez avec contrôle.','Technogym · Selection 900','Machine','Pectoraux',array['Réglez les appuis et les dispositifs de sécurité conformément au pictogramme de la machine.','Réglez le siège pour placer les poignées près du milieu de la poitrine. Poussez sans décoller le dos, puis revenez avec contrôle.','Revenez avec contrôle et conservez la même convention de charge à chaque séance.'],'Consignez la valeur affichée sur la pile ou la résistance choisie, sans conversion entre les machines. Sur les poulies, conservez le même montage et les mêmes accessoires.','Évitez l’élan et les amplitudes forcées. Une charge identique sur deux modèles différents ne représente pas nécessairement le même effort.','external',false) on conflict(id) do nothing;
insert into public.exercise_muscles values ('11000000-0000-4000-8000-164509db1b57','Pectoraux','primary'),('11000000-0000-4000-8000-164509db1b57','Triceps','secondary'),('11000000-0000-4000-8000-164509db1b57','Épaules','secondary') on conflict do nothing;
insert into public.exercises(id,name,english_name,description,category,equipment,primary_muscle,instructions,tips,mistakes,load_kind,supports_1rm) values ('11000000-0000-4000-8000-92c8c4e28bcb','Technogym Selection 900 — Pectoral (Écarté pectoral)','Selection 900 Pectoral','Ajustez les appuis à hauteur de poitrine. Rapprochez les bras avec les coudes légèrement fléchis, puis ouvrez sans forcer l’amplitude.','Technogym · Selection 900','Machine','Pectoraux',array['Réglez les appuis et les dispositifs de sécurité conformément au pictogramme de la machine.','Ajustez les appuis à hauteur de poitrine. Rapprochez les bras avec les coudes légèrement fléchis, puis ouvrez sans forcer l’amplitude.','Revenez avec contrôle et conservez la même convention de charge à chaque séance.'],'Consignez la valeur affichée sur la pile ou la résistance choisie, sans conversion entre les machines. Sur les poulies, conservez le même montage et les mêmes accessoires.','Évitez l’élan et les amplitudes forcées. Une charge identique sur deux modèles différents ne représente pas nécessairement le même effort.','external',false) on conflict(id) do nothing;
insert into public.exercise_muscles values ('11000000-0000-4000-8000-92c8c4e28bcb','Pectoraux','primary'),('11000000-0000-4000-8000-92c8c4e28bcb','Épaules','secondary') on conflict do nothing;
