insert into public.exercises(id,name,english_name,description,category,equipment,primary_muscle,instructions,tips,mistakes,load_kind,supports_1rm) values ('11000000-0000-4000-8000-c5ff78b86bf5','Technogym Element+ — Multi Hip · flexion (Flexion de hanche)','Element+ Multi Hip · flexion','Réglez le pivot à hauteur de hanche et l’appui devant la cuisse. Levez la cuisse sans basculer le bassin.','Technogym · Element+','Machine','Quadriceps',array['Réglez les appuis et les dispositifs de sécurité conformément au pictogramme de la machine.','Réglez le pivot à hauteur de hanche et l’appui devant la cuisse. Levez la cuisse sans basculer le bassin.','Revenez avec contrôle et conservez la même convention de charge à chaque séance.'],'Consignez la valeur affichée sur la pile ou la résistance choisie, sans conversion entre les machines. Sur les poulies, conservez le même montage et les mêmes accessoires.','Évitez l’élan et les amplitudes forcées. Une charge identique sur deux modèles différents ne représente pas nécessairement le même effort.','external',false) on conflict(id) do nothing;
insert into public.exercise_muscles values ('11000000-0000-4000-8000-c5ff78b86bf5','Quadriceps','primary'),('11000000-0000-4000-8000-c5ff78b86bf5','Abdominaux','secondary') on conflict do nothing;
insert into public.exercises(id,name,english_name,description,category,equipment,primary_muscle,instructions,tips,mistakes,load_kind,supports_1rm) values ('11000000-0000-4000-8000-b8c81638a467','Technogym Biostrength — Chest Press (Développé poitrine)','Biostrength Chest Press Biocircuit','Réglez le siège pour placer les poignées près du milieu de la poitrine. Poussez sans décoller le dos, puis revenez avec contrôle.','Technogym · Biostrength','Machine','Pectoraux',array['Réglez les appuis et les dispositifs de sécurité conformément au pictogramme de la machine.','Réglez le siège pour placer les poignées près du milieu de la poitrine. Poussez sans décoller le dos, puis revenez avec contrôle.','Revenez avec contrôle et conservez la même convention de charge à chaque séance.'],'Consignez la résistance affichée et le mode de travail dans les notes. Les modes de résistance différents ne sont pas directement comparables.','Évitez l’élan et les amplitudes forcées. Une charge identique sur deux modèles différents ne représente pas nécessairement le même effort.','external',false) on conflict(id) do nothing;
insert into public.exercise_muscles values ('11000000-0000-4000-8000-b8c81638a467','Pectoraux','primary'),('11000000-0000-4000-8000-b8c81638a467','Triceps','secondary'),('11000000-0000-4000-8000-b8c81638a467','Épaules','secondary') on conflict do nothing;
insert into public.exercises(id,name,english_name,description,category,equipment,primary_muscle,instructions,tips,mistakes,load_kind,supports_1rm) values ('11000000-0000-4000-8000-673370afce40','Technogym Biostrength — Vertical Traction (Tirage vertical)','Biostrength Vertical Traction Biocircuit','Calez les cuisses sous les appuis. Abaissez les épaules et tirez les coudes vers le bas, puis remontez progressivement.','Technogym · Biostrength','Machine','Dos',array['Réglez les appuis et les dispositifs de sécurité conformément au pictogramme de la machine.','Calez les cuisses sous les appuis. Abaissez les épaules et tirez les coudes vers le bas, puis remontez progressivement.','Revenez avec contrôle et conservez la même convention de charge à chaque séance.'],'Consignez la résistance affichée et le mode de travail dans les notes. Les modes de résistance différents ne sont pas directement comparables.','Évitez l’élan et les amplitudes forcées. Une charge identique sur deux modèles différents ne représente pas nécessairement le même effort.','external',false) on conflict(id) do nothing;
insert into public.exercise_muscles values ('11000000-0000-4000-8000-673370afce40','Dos','primary'),('11000000-0000-4000-8000-673370afce40','Biceps','secondary') on conflict do nothing;
