insert into public.exercises(id,name,english_name,description,category,equipment,primary_muscle,instructions,tips,mistakes,load_kind,supports_1rm) values ('11000000-0000-4000-8000-7cfad42b82a6','Technogym Unica — Lat Pulldown (Tirage vertical à la poulie)','Unica Lat Pulldown','Utilisez la station de tirage et ses appuis. Amenez la barre devant vous vers le haut de la poitrine, puis remontez avec contrôle.','Technogym · Unica','Poulie','Dos',array['Réglez les appuis et les dispositifs de sécurité conformément au pictogramme de la machine.','Utilisez la station de tirage et ses appuis. Amenez la barre devant vous vers le haut de la poitrine, puis remontez avec contrôle.','Revenez avec contrôle et conservez la même convention de charge à chaque séance.'],'Consignez la valeur affichée sur la pile ou la résistance choisie, sans conversion entre les machines. Sur les poulies, conservez le même montage et les mêmes accessoires.','Évitez l’élan et les amplitudes forcées. Une charge identique sur deux modèles différents ne représente pas nécessairement le même effort.','external',false) on conflict(id) do nothing;
