insert into public.exercises(id,name,english_name,description,category,equipment,primary_muscle,instructions,tips,mistakes,load_kind,supports_1rm) values ('11000000-0000-4000-8000-aba821773e14','Technogym Unica — Biceps Curl (Curl à la poulie)','Unica Biceps Curl','Placez la poulie en position basse. Fléchissez les coudes en gardant les bras près du buste.','Technogym · Unica','Poulie','Biceps',array['Réglez les appuis et les dispositifs de sécurité conformément au pictogramme de la machine.','Placez la poulie en position basse. Fléchissez les coudes en gardant les bras près du buste.','Revenez avec contrôle et conservez la même convention de charge à chaque séance.'],'Consignez la valeur affichée sur la pile ou la résistance choisie, sans conversion entre les machines. Sur les poulies, conservez le même montage et les mêmes accessoires.','Évitez l’élan et les amplitudes forcées. Une charge identique sur deux modèles différents ne représente pas nécessairement le même effort.','external',false) on conflict(id) do nothing;
