insert into public.exercises(id,name,english_name,description,category,equipment,primary_muscle,instructions,tips,mistakes,load_kind,supports_1rm) values ('11000000-0000-4000-8000-beb189c46beb','Technogym Excite — Run (Tapis de course)','Excite Run','Attachez le dispositif de sécurité si le tapis en possède un. Démarrez à faible vitesse, puis adaptez vitesse et inclinaison progressivement.','Technogym · Excite','Cardio','Quadriceps',array['Suivez les réglages et les indications de sécurité affichés sur ce modèle.','Attachez le dispositif de sécurité si le tapis en possède un. Démarrez à faible vitesse, puis adaptez vitesse et inclinaison progressivement.','Consignez manuellement la durée et, si elle est affichée, la distance de chaque intervalle.'],'Saisissez la durée réellement effectuée. La distance reste facultative pour les machines qui ne l’affichent pas ; indiquez résistance, inclinaison ou mode dans les notes.','Évitez les changements brusques d’allure et les réglages qui vous empêchent de garder des appuis stables.','cardio',false) on conflict(id) do nothing;
