insert into public.exercises(id,name,english_name,description,category,equipment,primary_muscle,instructions,tips,mistakes,load_kind,supports_1rm) values ('12000000-0000-4000-8000-000000000042','Extension triceps poulie · supination','Reverse grip triceps pushdown · barre droite supination','Paumes vers le haut, abaissez la barre avec les coudes fixes et une charge maîtrisée.','Barres, pupitres et prises','Poulie','Triceps',array['Réglez les appuis et fixez correctement l’accessoire avant de commencer.','Paumes vers le haut, abaissez la barre avec les coudes fixes et une charge maîtrisée.','Contrôlez le retour et conservez une amplitude confortable sans à-coups.'],'Gardez le même accessoire et la même prise pour comparer vos séances. Notez la charge totale barre comprise ; sur haltère, notez la charge par haltère et les répétitions par côté.','Évitez de changer d’accessoire au milieu d’un historique sans le noter, de casser les poignets ou d’utiliser l’élan du buste.','external',false) on conflict(id) do nothing;
insert into public.exercise_muscles values ('12000000-0000-4000-8000-000000000042','Triceps','primary') on conflict do nothing;
